import inspect
import re
from ..utilities.trs.commands.emssim import EmssimCommand
from ..utilities.trs import handler
from ..utilities.EmssAttribute import transform_dict_of_attributes_to_emss_input_list
from ..utilities.EmssAttribute import transform_dict_of_attributes_to_list
from time import sleep
import six


class EMSSInterface(object):
    """
    Base EMSsim keywords
    """

    def __init__(self):
        super(EMSSInterface, self).__init__()

    def get_emssim_command(self, command, enb_id=None, bts_id=None, alias=None):
        """
        Gets EMSsim command object for further processing.

        :param command: name of EMSsim command
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: EMSsim command object

        +---------------------------------+-------------+----------------+-----------------+
        |                                       Examples                                   |
        +=================================+=============+================+=================+
        | ${cmd_obj}=  get EMSsim command |  bts_connection_status                         |
        +---------------------------------+-------------+----------------+-----------------+
        | ${run_ok}=   Call Method        |  ${cmd_obj} | run                              |
        +---------------------------------+-------------+----------------+-----------------+
        | ${status}=   Call Method        |  ${cmd_obj} | get_status                       |
        +---------------------------------+-------------+----------------+-----------------+
        | Should Be Equal As Strings      |  ${status}  | Status.SUCCESS                   |
        +---------------------------------+-------------+----------------+-----------------+
        | ${started}=  Call Method        |  ${cmd_obj} | start                            |
        +---------------------------------+-------------+----------------+-----------------+
        | Call Method                     |  ${cmd_obj} | await_finish   | timeout=${30}   |
        +---------------------------------+-------------+----------------+-----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if isinstance(command, handler.DataHandler):
            return command

        cmd_object = None
        try:
            command_method = command
            if command[:4] != 'cmd_':
                command_method = 'cmd_' + command
            cmd_method = getattr(self._get_emssim(), command_method)
            cmd_object = cmd_method()
        except Exception:
            pass
        return cmd_object

    def run_emssim_command(self, command, params=None, timeout=None, get_full_data=False, can_fail=False,
                           enb_id=None, bts_id=None, alias=None, silent=False):
        """
        Runs EMSsim command

        :param command: name of EMSsim command or variable holding command object
        :param params: parameters of the command (optional, default = None), can be string or array of strings
        :param timeout: timeout to wait for command to complete, if not passed then use default command value
        :param get_full_data: (bool, default=False) return full command raw data
        :param can_fail: (bool, default=False) Mark that the command can fail, do not throw an exception on failure
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)

        +--------------------------------+----------------------------------------------+
        |                                       Examples                                |
        +================================+==============================================+
        | ${result}=  run EMSsim command |  cmd_bts_connection_status                   |
        +--------------------------------+----------------------------------------------+
        | ${result}=  run EMSsim command |  bts_connection_status                       |
        +--------------------------------+----------------------------------------------+
        | ${cmdobj}=  get EMSsim command |  bts_connection_status                       |
        +--------------------------------+----------------------------------------------+
        | ${result}=  run EMSsim command |  ${cmdobj}                                   |
        +--------------------------------+----------------------------------------------+
        """
        timeout = self._opt_int(timeout)
        get_full_data = self._opt_bool(get_full_data)
        can_fail = self._opt_bool(can_fail)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if command == "discover" or command == "load_pddb_data":
            self._clear_cache()

        if command == "edit" or command == "plan_send" or command == "padd":
            self._wa_for_pdl_validation()

        cmd_object = self.get_emssim_command(command, alias=alias)
        if cmd_object:
            if timeout:
                cmd_object.timeout = timeout
        else:
            if timeout is None:
                timeout = 60
            emssim = self._get_emssim()
            cmd_object = EmssimCommand(method=command, timeout=timeout, rpc_connection_name=emssim.rpc_connection_name)

        self._log("Run command: {}, params={}".format(command, params))
        func = cmd_object.run_silently if silent else cmd_object.run
        status = func(params)
        self._log("End command: {}, status={}".format(command, status))

        if not can_fail:
            self._assert(status, "Command execution failed (%s)" % command)

        if get_full_data:
            return cmd_object.get_data()
        else:
            return cmd_object.returned_data()

    def discover_bts(self, enb_id=None, bts_id=None, alias=None):
        """
        Discover BTS configuration
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------------------------+
        |                Examples                |
        +========================================+
        | discover bts                           |
        +----------------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command('discover', bts_id=bts_id, alias=alias)
        discover_status = self._get_discover_status()
        self._assert(discover_status, "BTS cannot be discovered")

    def enb_configuration_should_be_discovered(self, enb_id=None, bts_id=None, alias=None):
        """
        Verifies if BTS has already been discovered
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------------------------+
        |                Examples                |
        +========================================+
        | enb configuration should be discovered |
        +----------------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        discover_status = self._get_discover_status()
        if not discover_status:
            print("eNB is not discovered: re-executing setup emss.")
            self._run_setup_emss(wait_connected=True, wait_discovered=True)
            discover_status = self._get_discover_status()
        self._assert(discover_status, "eNB is not discovered")

    def get_adapt_version(self, adapt='NOKLTE', enb_id=None, bts_id=None, alias=None):
        """
        Return version of the given InfoModel adaptation

        :param adapt: name of the adaptation (default=NOKLTE)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------------+----------------------------------------------+
        |                                       Examples                                |
        +================================+==============================================+
        | ${version}=  get adapt version |  NOKLTE                                      |
        +--------------------------------+----------------------------------------------+
        | ${version}=  get adapt version |  com.nokia.mrbts                             |
        +--------------------------------+----------------------------------------------+
        | ${version}=  get adapt version |  com.nokia.srbts.eqm                         |
        +--------------------------------+----------------------------------------------+
        | ${version}=  get adapt version |  com.nokia.srbts.mnl                         |
        +--------------------------------+----------------------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        ret = self.run_emssim_command("env", bts_id=bts_id, alias=alias)

        self._assert('env' in ret, "Missing env (%s)" % ret)
        self._assert('BTS' in ret['env'], "Missing BTS in env (%s)" % ret['env'])
        self._assert('ADAPT_VERSION' in ret['env']['BTS'], "Missing ADAPT_VERSION in BTS (%s)" % ret['env']['BTS'])
        self._assert(adapt in ret['env']['BTS']['ADAPT_VERSION'], "Missing adapt=%s in ADAPT_VERSION (%s)" % (adapt, ret['env']['BTS']['ADAPT_VERSION']))
        return ret['env']['BTS']['ADAPT_VERSION'][adapt]

    def _format_comma_or_space_separated_string_given_by_user(self, comma_or_space_separated_string):
        self._assert(isinstance(comma_or_space_separated_string, six.string_types), "%s has to be a string" % comma_or_space_separated_string)

        if "," in comma_or_space_separated_string:
            output_list = str(comma_or_space_separated_string).replace(" ", "").split(",")
        else:
            output_list = str(comma_or_space_separated_string).split()
        return output_list

    def _edit_to_plan(self, object_name, dict_of_attributes):
        list_of_params = []
        list_of_params.extend(transform_dict_of_attributes_to_list(dict_of_attributes))
        params_dict = {}
        try:
            for i in range(0, len(list_of_params), 2):
                param = list_of_params[i]
                value = list_of_params[i + 1]
                if "[" in param:
                    if not self._edit_to_plan_struct(params_dict, param, value):
                        return None
                else:
                    params_dict[param] = value
        except Exception as exc:
            print("Cannot convert edit to plan: {}".format(exc))
            print("List of params: {}".format(list_of_params))
            return None

        for attr in params_dict:
            if isinstance(params_dict[attr], list):
                params_dict[attr] = [val for val in params_dict[attr] if val is not None]

        moc_id = object_name.split('-')
        params_dict['MOC'] = moc_id.pop(0)
        if moc_id:
            params_dict['ID'] = "-".join(moc_id)
        else:
            params_dict['ID'] = 'ALL'
        return params_dict

    def _edit_to_plan_struct(self, params_dict, param, value):
        srch = re.search(r"(\S+)\.(\S+)\[(\d+)\]", param)
        if srch:
            attr = srch.group(1)
            field = srch.group(2)
            index = int(srch.group(3))
            self._edit_to_plan_struct_put_with_field(params_dict, attr, value, field, index=index)
            return True

        srch = re.search(r"(\S+)\.(\S+)", param)
        if srch:
            attr = srch.group(1)
            field = srch.group(2)
            self._edit_to_plan_struct_put_with_field(params_dict, attr, value, field)
            return True

        srch = re.search(r"(\S+)\[(\d+)\]", param)
        if srch:
            attr = srch.group(1)
            index = int(srch.group(2))
            self._edit_to_plan_struct_put(params_dict, attr, value, index=index)
            return True

        print("WARNING: Unsupported plan format for structural attribute: {} {}".format(param, value))
        return False

    def _edit_to_plan_struct_put_with_field(self, params_dict, attr, value, field, index=0):
        attr_struct = {}

        if attr in params_dict:
            try:
                attr_struct = params_dict[attr][index]
            except Exception:
                pass
        else:
            params_dict[attr] = []

        attr_struct[field] = self._value_struct_to_value(value)

        try:
            params_dict[attr][index] = attr_struct
        except Exception:
            self._insert_table_at_with_expand(params_dict[attr], index, attr_struct)

    def _edit_to_plan_struct_put(self, params_dict, attr, value, index=0):
        if attr not in params_dict:
            params_dict[attr] = []
        value = self._value_struct_to_value(value)
        try:
            params_dict[attr][index] = value
        except Exception:
            self._insert_table_at_with_expand(params_dict[attr], index, value)

    def _insert_table_at_with_expand(self, table, index, value):
        if len(table) > index:
            table[index] = value
            return
        to_expand = index - len(table)
        for i in range(to_expand):
            table.append(None)
        table.append(value)

    def _value_struct_to_value(self, value):
        srch = re.search(r"\[(.*)\]", value)
        if srch:
            return srch.group(1)
        return value

    def _parse_edit_params(self, object_name, dict_of_attributes):
        list_of_params = [object_name]
        list_of_params.extend(transform_dict_of_attributes_to_emss_input_list(dict_of_attributes))
        return " ".join(list_of_params)

    def _case_insensitive_stings_comparison(self, string1, string2):
        return str(string1).lower() == str(string2).lower()

    def _error(self, msg):
        caller = ''
        stack = inspect.stack()
        if len(stack) > 0:
            parentframe = stack[1][0]
            caller = parentframe.f_code.co_name
        print("[%s] ERROR: %s" % (str(caller), str(msg)))

    def _should_repeat_command(self, command):
        if re.search(r"Missing values for mandatory parameters", command.failure_reason):
            return False

        ret = command.returned_data()
        if 'errors' in ret and re.search(r"Cause: busy", ret['errors']):
            return True
        if 'verror' in ret and isinstance(ret['verror'], list):
            for ve in ret['verror']:
                if re.search(r"BTS is not ready", ve):
                    return True
        for event in command.get_proxy_events():
            if re.search(r"GNSS SW update is ongoing", event):
                return True
            if re.search(r"CPlane is busy", event):
                return True
        return False

    def _should_retry_command_other_om(self, command):
        cmd_ret = command.returned_data()
        if 'json_admin_file_path' in cmd_ret:
            return True
        print("Command not for retry via other OM: %s" % cmd_ret)
        return False

    def _retry_command_via_other_om(self, command, *args, **kwargs):
        if self._is_config_wa_only():
            print("WA only: No retry via other OM")
            return False
        if self._is_config_admin():
            print("Retrying command via ADMIN")
            if self._delta_via_admin(command):
                return True
        if self._is_config_wa():
            print("Retrying command with WA")
            if self._retry_command_with_wa(command, *args, **kwargs):
                return True
        return False

    def _get_admin(self):
        admin = None
        try:
            from taf.sbts.oam.coam.admin import admin
            admin = admin()
            print("Using taf.sbts.oam.coam.admin as ADMIN")
        except Exception as exc:
            print("WARNING: Cannot make instance of taf.sbts.oam.coam.admin: {}".format(exc))
        return admin

    def _delta_via_admin(self, command):
        admin = self._get_admin()
        if admin is None:
            return False

        ret = False
        try:
            cmd_ret = command.returned_data()
            if 'full_scf_file_path' in cmd_ret:
                self._copy_file_to_log_dir(cmd_ret['full_scf_file_path'])

            json_file_path = cmd_ret['json_admin_file_path']
            json_plan_id = cmd_ret['json_admin_plan_id']
            alias = 'plan_' + json_plan_id
            self._copy_file_to_log_dir(json_file_path)
            bts_host = self._get_bts_ip()
            print("Setting ADMIN up: bts_host={}, bts_port=443, alias={}".format(bts_host, alias))
            admin.setup_admin(bts_host=bts_host, bts_port=443, use_ssl=True, name=alias)
            admin.perform_delta_recommissioning(json_file_path, skip_parameter_relation_errors=True, connection=alias)
            self.destroy_existing_plan()
            ret = True
        except Exception as exc:
            print("Cannot perform delta recommissioning via admin: {}".format(exc))
            ret = False
        finally:
            try:
                admin.teardown_admin(connection=alias)
            except Exception as exc:
                print("Cannot teardown admin: {}".format(exc))
        return ret

    def _retry_command_with_wa(self, command, *args, **kwargs):
        self._wa_for_pdl_validation(after_failure=True)
        return command.run(*args, **kwargs)

    def _run_repeat_command(self, command, *args, **kwargs):
        retry_limit = kwargs.pop('retry_limit', 3)
        retry_sleep = kwargs.pop('retry_sleep', 30)
        no_check_repeat = kwargs.pop('no_check_repeat', False)
        command_succeeded = command.run(*args, **kwargs)
        retry_count = 0
        while (retry_count < retry_limit) and not command_succeeded:
            if no_check_repeat or self._should_repeat_command(command):
                retry_count += 1
                print("EMSsim command failed. Retry {} after sleep {}...".format(retry_count, retry_sleep))
                sleep(retry_sleep)
                command_succeeded = command.run(*args, **kwargs)
            else:
                break

        if not command_succeeded:
            if self._should_retry_command_other_om(command):
                command_succeeded = self._retry_command_via_other_om(command, *args, **kwargs)
        return command_succeeded

    def _get_discover_status(self):
        try:
            emssim = self._get_emssim()

            c_status = emssim.cmd_bts_connection_status()
            c_status.run_silently()
            ret = c_status.returned_data()
            return int(ret['discover_status'])
        except Exception:
            return False

    def _get_bts_ip(self):
        ip_address = None
        try:
            ret = self.run_emssim_command("bts_get IP_ADDRESS", get_full_data=True)
            for data in ret:
                if 'value' in data:
                    ip_address = data['value']
        except Exception as exc:
            print("Cannot get BTS IP: {}".format(exc))
        return ip_address
